contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newKeeper, uint256 newThreshold) public payable {
        require(newThreshold <= 10_000);
        // Initially this contract is not the keeper (fresh deploy, arbitrary keeper),
        // so a keeper-only unpause attempt must revert.
        bool unpauseReverted;
        try c.unpauseDeposit() { unpauseReverted = false; } catch { unpauseReverted = true; }
        // Owner (this contract deployed c) updates admin configuration.
        c.setKeeper(newKeeper);
        c.setThresholds(newThreshold);
        assert(
            c.keeper() == newKeeper &&
            c.slippageThresholdGmxBps() == newThreshold &&
            unpauseReverted
        );
    }
    receive() external payable {}
}

