contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount, address receiver) public {
        require(amount > 0);
        require(receiver != address(0));
        require(amount <= type(uint128).max);

        uint256 balBefore = c.usdcBalance(receiver);
        uint256 roundBalBefore = c.roundUsdcBalance();
        uint256 roundBefore = c.currentRound();

        c.depositUsdc(amount, receiver);

        uint256 balAfter = c.usdcBalance(receiver);
        uint256 roundBalAfter = c.roundUsdcBalance();
        uint256 roundAfter = c.currentRound();

