contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint256 amount, address receiver) public {
        require(amount > 0);
        require(receiver != address(0));

        // initialize with this contract acting as keeper, vault and (mock) externals
        c.initialize(
            IERC20(address(this)),
            IERC20(address(this)),
            IRewardRouterV2(address(this)),
            IGlpManager(address(this)),
            address(this),
            address(this)
        );

        uint256 sharesBefore = c.unclaimedShares(address(this));

        // claim to zero-address receiver must revert
        bool rZero;
        try c.claim(address(0), amount) { rZero = false; } catch { rZero = true; }

        // claim of one share more than unclaimed must revert
        bool rExcess;
        try c.claim(receiver, sharesBefore + 1) { rExcess = false; } catch { rExcess = true; }

        // claim within the unclaimed balance must not revert
        bool rValid;
        try c.claim(receiver, amount) { rValid = false; } catch { rValid = true; }

        assert(
            rZero &&
            rExcess &&
            (amount > sharesBefore ? rValid : !rValid)
        );
    }

    fallback(bytes calldata) external returns (bytes memory) {
        // mock: transfer()/transferFrom()/approve() return true, vault() returns an address
        return abi.encode(true);
    }

    receive() external payable {}
}

